head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL55210";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil55210.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const opener = scwin.openerScwin();
        const specialChars = /-/;
        $c.util.getComponent('ipt_prtdepoId').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).prtdepoId));
        $c.util.getComponent('ipt_shrhdNm').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).shrhdNm));
        $c.util.getComponent('ipt_lstPrtdepoShrs').setValue($c.num.formatNumber((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).lstPrtdepoShrs));
        $c.util.getComponent('ipt_bzProcsNo').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).bzProcsNo));
        $c.util.getComponent('ipt_prtdepoWithdApplSeq').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).prtdepoWithdApplSeq));
        $c.util.getComponent('cal_prtdepoStrtDd').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).prtdepoStrtDd).split(specialChars).join(""));
        $c.util.getComponent('cal_prtdepoEndDd').setValue(((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).prtdepoEndDd).split(specialChars).join(""));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55210.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_lstPrtdepoShrs_onkeyup
 * @description ipt_lstPrtdepoShrs 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_lstPrtdepoShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55210.ipt_lstPrtdepoShrs_onkeyup' }); }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancel_onclick = function(e){
    try {
        scwin.cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55210.btn_cancel_onclick' }); }
};

/**
 * @method
 * @name btn_saveLstPrtdepoShrs_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_saveLstPrtdepoShrs_onclick = async function(e){
    try {
        await scwin.saveLstPrtdepoShrs()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55210.btn_saveLstPrtdepoShrs_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name saveLstPrtdepoShrs
 * @description save Lst Prtdepo Shrs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveLstPrtdepoShrs = async function () {
    const opener = scwin.openerScwin();
    const frm = $c.util.getComponent('form_6');
    if (await scwin.validate()) {
        frm.target = 'prtdepoWin';
        frm.submit();
        await $c.win.alert('수정 되었습니다');
        opener.calcelYn = 'N';
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'Y';
    $c.win.closePopup();
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (($c.util.getComponent('cal_prtdepoStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoStrtDd').getValue())) === '') {
        await $c.win.alert("의무보유기간을 입력하십시요.");
        $c.util.getComponent("cal_prtdepoStrtDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_prtdepoEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoEndDd').getValue())) === '') {
        await $c.win.alert("의무보유기간을 입력하십시요.");
        $c.util.getComponent("cal_prtdepoEndDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_prtdepoStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoStrtDd').getValue())) !== '' && ($c.util.getComponent('cal_prtdepoEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoEndDd').getValue())) !== '') {
        if ($c.util.getComponent('cal_prtdepoStrtDd').getValue()> $c.util.getComponent('cal_prtdepoEndDd').getValue()) {
            await $c.win.alert("의무보유시작일이 종료일보다 이후 일자 입니다.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    if (($c.util.getComponent('ipt_lstPrtdepoShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_lstPrtdepoShrs').getValue())) === '') {
        await $c.win.alert("최종의무보유주식수를 입력하세요.");
        $c.util.getComponent("ipt_lstPrtdepoShrs").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    return true;
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
